using ProjetoIntegradorBack.Api.Queries; using ProjetoIntegradorBack.Domain.DTOs; using ProjetoIntegradorBack.Domain.Interfaces; using Prime.Architecture.Mapper.Interfaces; using Prime.Architecture.Mediator.Standard.Requests;
namespace ProjetoIntegradorBack.Api.Handlers.NavalhaCorte;
public class ListEstablishmentsHandler(IEstablishmentRepository r,IMapper m):IRequestHandler<ListEstablishmentsQuery,PagedResultDto<EstablishmentDto>> { public async Task<PagedResultDto<EstablishmentDto>> Handle(ListEstablishmentsQuery q,CancellationToken ct){var x=await r.ListAsync(q.Busca,q.City,q.Page,q.Tamanho,ct);var t=await r.ContarAsync(q.Busca,q.City,ct);return new(){Data=x.IsSuccess?x.Success!.Select(e=>m.Map<Domain.Entities.Establishment,EstablishmentDto>(e)).ToList():[],Page=q.Page,PageSize=q.Tamanho,Total=t.IsSuccess?t.Success:0};}}
public class GetEstablishmentHandler(IEstablishmentRepository r,IMapper m):IRequestHandler<GetEstablishmentQuery,EstablishmentDetailsDto>{public async Task<EstablishmentDetailsDto> Handle(GetEstablishmentQuery q,CancellationToken ct){var x=await r.GetPorIdAsync(q.Id,ct);if(x.IsFailure)throw new KeyNotFoundException();return m.Map<Domain.Entities.Establishment,EstablishmentDetailsDto>(x.Success!);}}
